/** Source: trade.c → CB2_LinkTrade */
export const CB2_LinkTrade: CB2Callback = (rt) => {
  switch (gMain.state)
      {
      case 0:
          if (!gReceivedRemoteLinkPlayers)
          {
              gLinkType = LINKTYPE_TRADE_DISCONNECTED;
              CloseLink();
          }
          sTradeAnim = AllocZeroed(((sTradeAnim)?.length ?? 32));
          AllocateMonSpritesGfx();
          ResetTasks();
          rt.ResetSpriteData();
          FreeAllSpritePalettes();
          /* noop SetVBlankCallback */;
          TradeAnimInit_LoadGfx();
          ClearLinkTimeoutTimer();
          gMain.state++;
          sTradeAnim.neverRead_8C = 0;
          sTradeAnim.state = 0;
          sTradeAnim.isLinkTrade = true;
          sTradeAnim.texX = 64;
          sTradeAnim.texY = 64;
          sTradeAnim.neverRead_D8 = 0;
          sTradeAnim.neverRead_DA = 0;sTradeAnim.scrX = Math.trunc(DISPLAY_WIDTH / 2);
  sTradeAnim.scrY = Math.trunc(DISPLAY_HEIGHT / 2);
          sTradeAnim.sXY = 256;
          sTradeAnim.alpha = 0;
          break;
      case 1:
          if (!gReceivedRemoteLinkPlayers)
          {
              sTradeAnim.isCableTrade = true;
              OpenLink();
              gMain.state++;
              sTradeAnim.timer = 0;
          }
          else
          {
              gMain.state = 4;
          }
          break;
      case 2:
          if (++sTradeAnim.timer > 60)
          {
              sTradeAnim.timer = 0;
              gMain.state++;
          }
          break;
      case 3:
          if (IsLinkMaster())
          {
              if (GetLinkPlayerCount_2() >= GetSavedPlayerCount())
              {
                  if (++sTradeAnim.timer > 30)
                  {
                      CheckShouldAdvanceLinkState();
                      gMain.state++;
                  }
              }
              else
              {
                  CheckForLinkTimeout();
              }
          }
          else
          {
              gMain.state++;
          }
          break;
      case 4:
          CheckForLinkTimeout();
          if (gReceivedRemoteLinkPlayers == true && IsLinkPlayerDataExchangeComplete() == true)
              gMain.state++;
          break;
      case 5:
          sTradeAnim.playerFinishStatus = 0;
          sTradeAnim.partnerFinishStatus = 0;
          sTradeAnim.scheduleLinkTransfer = 0;
          LoadTradeMonPic(TRADE_PLAYER, 0);
          gMain.state++;
          break;
      case 6:
          LoadTradeMonPic(TRADE_PLAYER, 1);
          gMain.state++;
          break;
      case 7:
          LoadTradeMonPic(TRADE_PARTNER, 0);
          gMain.state++;
          break;
      case 8:
          LoadTradeMonPic(TRADE_PARTNER, 1);
          LinkTradeDrawWindow();
          gMain.state++;
          break;
      case 9:
          LoadTradeSequenceSpriteSheetsAndPalettes();
          LoadSpriteSheet(sPokeBallSpriteSheet);
          LoadSpritePalette(sPokeBallSpritePalette);
          gMain.state++;
          break;
      case 10:
          rt.BeginNormalPaletteFade("PALETTES_ALL", 0, 16, 0, "RGB_BLACK");
          ShowBg(0);
          gMain.state++;
          break;
      case 11:
          InitTradeSequenceBgGpuRegs();
          BufferTradeSceneStrings();
          gMain.state++;
          break;
      case 12:
          if (!rt.gPaletteFade.active)
          {
              if (gWirelessCommType)
              {
                  LoadWirelessStatusIndicatorSpriteGfx();
                  CreateWirelessStatusIndicatorSprite(0, 0);
              }
              /* TODO scene transition: SetMainCallback2(CB2_UpdateLinkTrade) */;
          }
          break;
      }
      RunTasks();
      RunTextPrinters();
      AnimateSprites();
      BuildOamBuffer();
      UpdatePaletteFade();
};

